mapper.select:
SELECT a.event_id FROM applications a JOIN events e ON e.id = a.event_id WHERE a.user_id = #{userId} AND e.end_at > now()
AND e.community_id = #{communityId}
ORDER BY a.event_id

SELECT my.status,  AS waitlist_position, my.applied_at
FROM applications my
WHERE my.event_id = #{eventId} AND my.user_id = #{userId}

SELECT x.user_id, x.nickname, x.status, x.waitlist_position, x.applied_at
FROM (
    SELECT 
    FROM applications a
    JOIN users u ON u.id = a.user_id
    WHERE a.event_id = #{eventId}
) x
WHERE x.user_id = #{userId}
